test:
set +x
set -eu
headers=$(curl --disable --silent --noproxy '*' --connect-timeout 3 --max-time 8 \
  --header "Host: $2" --dump-header - --output /dev/null --write-out '\n%{http_code}' "http://$3/") || exit 1
case "$(printf '%s\n' "$headers" | tail -n 1)" in
  2[0-9][0-9]|3[0-9][0-9]) exit 0 ;;
  503) ;;
  *) exit 1 ;;
esac

# Joomla starts a guest session before selecting its offline template. The
# session provider hashes the secret and configured session_name (also used
# for shared sessions); CMS Session hashes that name again for the cookie.
cookie=$(php -d register_argc_argv=1 -r '
  try {
    require $argv[1]."/configuration.php"; $config=new JConfig();
    if (empty($config->offline) || ($config->secret ?? "") === "") exit(1);
    $name = $config->session_name ?? "";
    echo md5(md5($config->secret . ($name === "" ? "site" : $name)));
  } catch (Throwable $e) { exit(1); }
' -- "$1" 2>/dev/null) || exit 1
[ -n "$cookie" ] || exit 1

# Ignore interim response headers. Check only the cookie name and discard its value.
printf '%s\n' "$headers" | awk -v cookie="$cookie" '
  /^HTTP\/[0-9.]+[[:space:]]/ {issued=0}
  tolower(substr($0,1,11))=="set-cookie:" {
    field=substr($0,12); sub(/^[[:blank:]]*/, "", field)
    if (index(field,cookie "=")==1 && substr(field,length(cookie)+2,1) ~ /[^;[:space:]]/) issued=1
  }
  END {exit !issued}'
